Partial.wizardCreateBranchDone = function(widget, steps) {
  let members = Partial.Widgets.containerAddMembersToBranch.Widgets.listBranchMembers.dataset.filter(item => item.isChecked);
  members.forEach(m => { delete m.isChecked; delete m.alias; });

  Partial.Variables.swgCreateBranchProject.invoke({
    inputFields: {
      projectBranchRequest: {
        copyUsers: App.isCopyUsers == false ? false : members.length === Partial.Widgets.containerAddMembersToBranch.Widgets.listBranchMembers.dataset.length,
        vcsBranch: Partial.Widgets.containerCreateBranchStep1.Widgets.mdCreateBranchForm1.dataoutput['vcsBranch'].name,
        projectUserMappingList: App.isCopyUsers === "true" ? [] : members
      },
      project_id: App.allowedActionsSelectedItem.projectId
    }
  });

  $('button[name="doneBtn_wizardCreateBranch"]').prop('disabled', true);
};

